window.GENERATED_MODULES.push(.../*__DATA_START__*/[{"id":"gen-gk-current-affairs-2026-09-05-mto4gtwc","subject":"gk","day":0,"level":1,"title":"Current Affairs","hi":"समसामयिकी","concepts":[{"title":"Recent Events and Developments","title_hi":"हाल की घटनाएं और विकास","simple":"Current affairs are important recent events happening around the world.","simple_hi":"समसामयिकी का मतलब है दुनिया में हाल ही में होने वाली महत्वपूर्ण घटनाएं।","intro":"","points":["Current affairs include news about politics, sports, science, and more. (समसामयिकी में राजनीति, खेल, विज्ञान आदि की खबरें शामिल हैं।)","They help us stay informed and are often asked in exams. (इनसे हमें जानकारी मिलती है और परीक्षाओं में अक्सर पूछा जाता है।)","Important dates, awards, and appointments are common topics. (महत्वपूर्ण तिथियाँ, पुरस्कार और नियुक्तियाँ सामान्य विषय हैं।)","Current affairs change daily, so regular reading is needed. (समसामयिकी प्रतिदिन बदलती है, इसलिए नियमित पढ़ना आवश्यक है।)"],"example":"For example, if India wins a cricket match, that is current affairs. Similarly, if a new chief minister is sworn in, that is also current affairs. (उदाहरण के लिए, अगर भारत क्रिकेट मैच जीतता है, तो वह समसामयिकी है। इसी तरह, अगर कोई नया मुख्यमंत्री शपथ लेता है, तो वह भी समसामयिकी है।)","trick":"Remember 'CA' as 'Current Affairs' – like a daily newspaper. (CA को 'Current Affairs' के रूप में याद रखें – जैसे दैनिक समाचार पत्र।)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"In exams, current affairs questions often come from the last 6 months. So, focus on recent major events, government schemes, and international summits. Also, note that some questions may be based on static events like important days. (परीक्षाओं में, समसामयिकी के प्रश्न अक्सर पिछले 6 महीनों से आते हैं। इसलिए, हाल की प्रमुख घटनाओं, सरकारी योजनाओं और अंतरराष्ट्रीय शिखर सम्मेलनों पर ध्यान दें। साथ ही, कुछ प्रश्न स्थिर घटनाओं जैसे महत्वपूर्ण दिनों पर आधारित हो सकते हैं।)","body_hi":"In exams, current affairs questions often come from the last 6 months. So, focus on recent major events, government schemes, and international summits. Also, note that some questions may be based on static events like important days. (परीक्षाओं में, समसामयिकी के प्रश्न अक्सर पिछले 6 महीनों से आते हैं। इसलिए, हाल की प्रमुख घटनाओं, सरकारी योजनाओं और अंतरराष्ट्रीय शिखर सम्मेलनों पर ध्यान दें। साथ ही, कुछ प्रश्न स्थिर घटनाओं जैसे महत्वपूर्ण दिनों पर आधारित हो सकते हैं।)"}}],"questions":[{"q":"Who is the current Chief Minister of Uttar Pradesh as of September 2026?","q_hi":"सितंबर 2026 तक उत्तर प्रदेश के मुख्यमंत्री कौन हैं?","o":["Yogi Adityanath","Akhilesh Yadav","Mayawati","Rahul Gandhi"],"o_hi":["योगी आदित्यनाथ","अखिलेश यादव","मायावती","राहुल गांधी"],"a":0,"exp":"Yogi Adityanath is the Chief Minister of Uttar Pradesh since 2017.","exp_hi":"योगी आदित्यनाथ 2017 से उत्तर प्रदेश के मुख्यमंत्री हैं।","why":["Akhilesh Yadav was CM from 2012 to 2017, not now.","Mayawati was CM earlier, not now.","Rahul Gandhi is a Member of Parliament, not CM."],"topic":"State Government","level":1,"mode":"standard"},{"q":"Which country hosted the 2026 FIFA World Cup?","q_hi":"2026 फीफा विश्व कप की मेजबानी किस देश ने की?","o":["USA, Canada and Mexico","Qatar","Russia","Brazil"],"o_hi":["अमेरिका, कनाडा और मैक्सिको","कतर","रूस","ब्राज़ील"],"a":0,"exp":"The 2026 FIFA World Cup is being hosted by the United States, Canada, and Mexico.","exp_hi":"2026 फीफा विश्व कप की मेजबानी संयुक्त राज्य अमेरिका, कनाडा और मैक्सिको द्वारा की जा रही है।","why":["Qatar hosted the 2022 World Cup.","Russia hosted the 2018 World Cup.","Brazil hosted the 2014 World Cup."],"topic":"Sports","level":1,"mode":"standard"},{"q":"What is the theme of World Environment Day 2026?","q_hi":"विश्व पर्यावरण दिवस 2026 की थीम क्या है?","o":["Land Restoration, Desertification and Drought Resilience","Beat Plastic Pollution","Air Pollution","Biodiversity"],"o_hi":["भूमि बहाली, मरुस्थलीकरण और सूखा सहनशीलता","प्लास्टिक प्रदूषण को हराएं","वायु प्रदूषण","जैव विविधता"],"a":0,"exp":"The theme for World Environment Day 2026 is 'Land Restoration, Desertification and Drought Resilience'.","exp_hi":"विश्व पर्यावरण दिवस 2026 की थीम 'भूमि बहाली, मरुस्थलीकरण और सूखा सहनशीलता' है।","why":["Beat Plastic Pollution was the theme for 2023.","Air Pollution was the theme for 2019.","Biodiversity was the theme for 2020."],"topic":"Environment","level":2,"mode":"standard"},{"q":"Who was awarded the Bharat Ratna in 2026?","q_hi":"2026 में भारत रत्न किसे प्रदान किया गया?","o":["Lata Mangeshkar","Sachin Tendulkar","M. S. Swaminathan","Pranab Mukherjee"],"o_hi":["लता मंगेशकर","सचिन तेंदुलकर","एम. एस. स्वामीनाथन","प्रणब मुखर्जी"],"a":2,"exp":"M. S. Swaminathan, known as the father of India's Green Revolution, was awarded the Bharat Ratna in 2026.","exp_hi":"भारत के हरित क्रांति के जनक कहे जाने वाले एम. एस. स्वामीनाथन को 2026 में भारत रत्न प्रदान किया गया।","why":["Lata Mangeshkar received Bharat Ratna in 2001.","Sachin Tendulkar received Bharat Ratna in 2014.","Pranab Mukherjee received Bharat Ratna in 2019."],"topic":"Awards","level":2,"mode":"standard"},{"q":"Which Indian state launched the 'Mukhyamantri Yuva Udyami Yojana' in 2026?","q_hi":"2026 में किस भारतीय राज्य ने 'मुख्यमंत्री युवा उद्यमी योजना' शुरू की?","o":["Uttar Pradesh","Bihar","Madhya Pradesh","Rajasthan"],"o_hi":["उत्तर प्रदेश","बिहार","मध्य प्रदेश","राजस्थान"],"a":0,"exp":"Uttar Pradesh launched the 'Mukhyamantri Yuva Udyami Yojana' in 2026 to promote entrepreneurship among youth.","exp_hi":"उत्तर प्रदेश ने युवाओं में उद्यमिता को बढ़ावा देने के लिए 2026 में 'मुख्यमंत्री युवा उद्यमी योजना' शुरू की।","why":["Bihar has its own schemes but not this one.","Madhya Pradesh has different schemes.","Rajasthan has different schemes."],"topic":"Government Schemes","level":2,"mode":"standard"},{"q":"What is the currency of the newly formed country 'XYZ' (fictional) in 2026?","q_hi":"2026 में नए बने देश 'XYZ' (काल्पनिक) की मुद्रा क्या है?","o":["Dinar","Rupee","Peso","Crown"],"o_hi":["दीनार","रुपया","पेसो","क्राउन"],"a":0,"exp":"This is a hypothetical question; in reality, no such country exists. In exams, such questions are not asked. But for practice, we assume the currency is Dinar.","exp_hi":"यह एक काल्पनिक प्रश्न है; वास्तव में ऐसा कोई देश मौजूद नहीं है। परीक्षाओं में ऐसे प्रश्न नहीं पूछे जाते। लेकिन अभ्यास के लिए, हम मान लेते हैं कि मुद्रा दीनार है।","why":["Rupee is used in India and some other countries.","Peso is used in many Latin American countries.","Crown is used in some European countries."],"topic":"International Affairs","level":3,"mode":"standard"}]},{"id":"gen-gk-indian-polity-governance-mto4h7p9","subject":"gk","day":0,"level":1,"title":"Indian Polity & Governance","hi":"भारतीय राजनीति एवं शासन व्यवस्था","concepts":[{"title":"Key Features of Indian Polity","title_hi":"भारतीय राजनीति की प्रमुख विशेषताएँ","simple":"India is a democratic country where the people elect their leaders.","simple_hi":"भारत एक लोकतांत्रिक देश है जहाँ लोग अपने नेताओं को चुनते हैं।","intro":"","points":["भारत का संविधान 26 नवंबर 1949 को बना और 26 जनवरी 1950 से लागू हुआ। (The Indian Constitution was made on 26 Nov 1949 and came into force on 26 Jan 1950.)","भारत एक संसदीय प्रणाली है, जहाँ प्रधानमंत्री सरकार का प्रमुख होता है। (India has a parliamentary system where the Prime Minister is the head of government.)","राष्ट्रपति देश का प्रथम नागरिक और संवैधानिक प्रमुख होता है। (The President is the first citizen and constitutional head of the country.)","संविधान में मौलिक अधिकार (Fundamental Rights) नागरिकों को दिए गए हैं। (The Constitution grants Fundamental Rights to citizens.)","भारत में तीन स्तर की सरकारें हैं: केंद्र, राज्य और स्थानीय। (India has three levels of government: central, state, and local.)"],"example":"जैसे हमारे विद्यालय में प्रधानाचार्य (Principal) होते हैं, वैसे ही देश में राष्ट्रपति होते हैं। लेकिन असली काम प्रधानमंत्री (Prime Minister) और मंत्री (Ministers) करते हैं, जैसे विद्यालय में उप-प्रधानाचार्य और शिक्षक। (Just as a school has a Principal, the country has a President. But the real work is done by the Prime Minister and Ministers, like the Vice-Principal and teachers.)","trick":"याद रखें: 'संसद' = सोचो + समझो + कानून बनाओ। (Remember: 'Parliament' = Think + Discuss + Make laws.)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"भारत का संविधान विश्व का सबसे लंबा लिखित संविधान है। इसमें संघीय ढाँचा (federal structure) है, लेकिन केंद्र सरकार को अधिक शक्तियाँ दी गई हैं। यह 'संघीय व्यवस्था' और 'एकात्मक भावना' का मिश्रण है। (India's Constitution is the world's longest written constitution. It has a federal structure but gives more powers to the central government. It is a mix of federal system and unitary spirit.)","body_hi":"भारत का संविधान विश्व का सबसे लंबा लिखित संविधान है। इसमें संघीय ढाँचा (federal structure) है, लेकिन केंद्र सरकार को अधिक शक्तियाँ दी गई हैं। यह 'संघीय व्यवस्था' और 'एकात्मक भावना' का मिश्रण है। (India's Constitution is the world's longest written constitution. It has a federal structure but gives more powers to the central government. It is a mix of federal system and unitary spirit.)"}}],"questions":[{"q":"Who is the constitutional head of the Indian government?","q_hi":"भारतीय सरकार का संवैधानिक प्रमुख कौन होता है?","o":["Prime Minister","President","Chief Justice of India","Vice President"],"o_hi":["प्रधानमंत्री","राष्ट्रपति","भारत के मुख्य न्यायाधीश","उपराष्ट्रपति"],"a":1,"exp":"The President is the constitutional head of the Indian government, while the Prime Minister is the executive head.","exp_hi":"राष्ट्रपति भारतीय सरकार का संवैधानिक प्रमुख है, जबकि प्रधानमंत्री कार्यपालिका का प्रमुख होता है।","why":["प्रधानमंत्री सरकार का वास्तविक प्रमुख होता है, लेकिन संवैधानिक प्रमुख नहीं।","मुख्य न्यायाधीश न्यायपालिका का प्रमुख होता है, सरकार का नहीं।","उपराष्ट्रपति राज्यसभा का सभापति होता है, संवैधानिक प्रमुख नहीं।"],"topic":"Indian Polity","level":1,"mode":"standard"},{"q":"Which of the following is a Fundamental Right guaranteed by the Indian Constitution?","q_hi":"निम्नलिखित में से कौन सा भारतीय संविधान द्वारा प्रदत्त मौलिक अधिकार है?","o":["Right to Property","Right to Equality","Right to Work","Right to Free Education"],"o_hi":["संपत्ति का अधिकार","समानता का अधिकार","काम का अधिकार","निःशुल्क शिक्षा का अधिकार"],"a":1,"exp":"Right to Equality is a Fundamental Right under Article 14-18. Right to Property was removed from Fundamental Rights by the 44th Amendment.","exp_hi":"समानता का अधिकार अनुच्छेद 14-18 के अंतर्गत मौलिक अधिकार है। संपत्ति का अधिकार 44वें संशोधन द्वारा मौलिक अधिकारों से हटा दिया गया।","why":["संपत्ति का अधिकार अब मौलिक अधिकार नहीं है, यह कानूनी अधिकार है।","काम का अधिकार मौलिक अधिकार नहीं है, यह नीति-निर्देशक सिद्धांत है।","निःशुल्क शिक्षा का अधिकार 6-14 वर्ष के बच्चों के लिए है, लेकिन यह अनुच्छेद 21A में है, जो मौलिक अधिकार है, लेकिन 'Right to Free Education' सही नाम नहीं है।"],"topic":"Fundamental Rights","level":1,"mode":"standard"},{"q":"The Constitution of India was adopted on which date?","q_hi":"भारतीय संविधान किस तिथि को अपनाया गया था?","o":["26 January 1950","15 August 1947","26 November 1949","2 October 1948"],"o_hi":["26 जनवरी 1950","15 अगस्त 1947","26 नवंबर 1949","2 अक्टूबर 1948"],"a":2,"exp":"The Constitution was adopted on 26 November 1949, and it came into effect on 26 January 1950.","exp_hi":"संविधान 26 नवंबर 1949 को अपनाया गया था और 26 जनवरी 1950 को लागू हुआ।","why":["26 जनवरी 1950 वह तारीख है जब संविधान लागू हुआ था, न कि अपनाया गया था।","15 अगस्त 1947 भारत की स्वतंत्रता की तारीख है।","2 अक्टूबर 1948 महात्मा गांधी की जयंती है, संविधान से संबंधित नहीं।"],"topic":"Constitution","level":1,"mode":"standard"},{"q":"Which of the following is NOT a feature of the Indian Constitution?","q_hi":"निम्नलिखित में से कौन सा भारतीय संविधान की विशेषता नहीं है?","o":["Parliamentary system","Federal system","Presidential system","Independent judiciary"],"o_hi":["संसदीय प्रणाली","संघीय प्रणाली","राष्ट्रपति प्रणाली","स्वतंत्र न्यायपालिका"],"a":2,"exp":"India follows a parliamentary system, not a presidential system. In a presidential system, the President is both head of state and government.","exp_hi":"भारत संसदीय प्रणाली का पालन करता है, राष्ट्रपति प्रणाली का नहीं। राष्ट्रपति प्रणाली में राष्ट्रपति राज्य और सरकार दोनों का प्रमुख होता है।","why":["संसदीय प्रणाली भारत की विशेषता है, इसलिए यह गलत नहीं है।","संघीय प्रणाली भारत में है, इसलिए यह गलत नहीं है।","स्वतंत्र न्यायपालिका भारत में है, इसलिए यह गलत नहीं है।"],"topic":"Constitution Features","level":1,"mode":"standard"},{"q":"Who appoints the Prime Minister of India?","q_hi":"भारत के प्रधानमंत्री की नियुक्ति कौन करता है?","o":["President","Vice President","Lok Sabha Speaker","Chief Justice of India"],"o_hi":["राष्ट्रपति","उपराष्ट्रपति","लोकसभा अध्यक्ष","भारत के मुख्य न्यायाधीश"],"a":0,"exp":"The President appoints the Prime Minister. Usually, the leader of the majority party in Lok Sabha is appointed.","exp_hi":"राष्ट्रपति प्रधानमंत्री की नियुक्ति करता है। आमतौर पर लोकसभा में बहुमत दल का नेता नियुक्त किया जाता है।","why":["उपराष्ट्रपति प्रधानमंत्री की नियुक्ति नहीं करता।","लोकसभा अध्यक्ष सदन का पीठासीन अधिकारी होता है।","मुख्य न्यायाधीश न्यायपालिका का प्रमुख होता है।"],"topic":"Executive","level":1,"mode":"standard"},{"q":"Which article of the Indian Constitution deals with the Right to Constitutional Remedies?","q_hi":"भारतीय संविधान का कौन सा अनुच्छेद संवैधानिक उपचारों के अधिकार से संबंधित है?","o":["Article 32","Article 21","Article 14","Article 19"],"o_hi":["अनुच्छेद 32","अनुच्छेद 21","अनुच्छेद 14","अनुच्छेद 19"],"a":0,"exp":"Article 32 gives the right to move the Supreme Court for enforcement of Fundamental Rights. Dr. Ambedkar called it the 'heart and soul' of the Constitution.","exp_hi":"अनुच्छेद 32 मौलिक अधिकारों के प्रवर्तन के लिए उच्चतम न्यायालय जाने का अधिकार देता है। डॉ. आंबेडकर ने इसे संविधान की 'आत्मा' कहा।","why":["अनुच्छेद 21 जीवन और व्यक्तिगत स्वतंत्रता का अधिकार है।","अनुच्छेद 14 समानता का अधिकार है।","अनुच्छेद 19 स्वतंत्रता के अधिकार से संबंधित है।"],"topic":"Fundamental Rights","level":2,"mode":"standard"}]},{"id":"gen-gk-science-technology-space-defence-it-mto4houy","subject":"gk","day":0,"level":1,"title":"Science & Technology: Space, Defence, IT","hi":"विज्ञान और प्रौद्योगिकी: अंतरिक्ष, रक्षा, सूचना प्रौद्योगिकी","concepts":[{"title":"Key Developments in Space, Defence, and IT","title_hi":"अंतरिक्ष, रक्षा और सूचना प्रौद्योगिकी में प्रमुख विकास","simple":"Science and technology helps us explore space, protect our country, and use computers.","simple_hi":"विज्ञान और प्रौद्योगिकी हमें अंतरिक्ष की खोज, देश की रक्षा और कंप्यूटर के उपयोग में मदद करती है।","intro":"","points":["ISRO is India's space agency; it launched Chandrayaan and Mangalyaan. (इसरो भारत की अंतरिक्ष एजेंसी है; इसने चंद्रयान और मंगलयान लॉन्च किए।)","India's first satellite was Aryabhata (1975). (भारत का पहला उपग्रह आर्यभट्ट (1975) था।)","Agni and Prithvi are India's missile systems. (अग्नि और पृथ्वी भारत की मिसाइल प्रणाली हैं।)","IT means Information Technology; it deals with computers and the internet. (आईटी का अर्थ सूचना प्रौद्योगिकी है; यह कंप्यूटर और इंटरनेट से संबंधित है।)","India's supercomputer 'Param' is used for complex calculations. (भारत का सुपरकंप्यूटर 'परम' जटिल गणनाओं के लिए प्रयोग होता है।)"],"example":"Think of ISRO like a space postman. It sends satellites (like letters) to space using rockets. For example, Chandrayaan-1 (2008) found water on the Moon. Similarly, Mangalyaan (2014) reached Mars successfully. In defence, India has missiles like Agni-V which can travel long distances. In IT, we use computers and the internet daily, like sending emails or browsing websites.","trick":"Remember 'A-P-I' for Space, Defence, IT: A for Aryabhata (first satellite), P for Prithvi (missile), I for Internet (IT).","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"In space, ISRO's GSLV and PSLV are launch vehicles; PSLV is known for its reliability. In defence, India's Integrated Guided Missile Development Programme (IGMDP) developed Agni, Prithvi, Akash, Trishul, and Nag. In IT, India is a major hub for software services, and 'Digital India' is a government initiative to connect rural areas with the internet. These fields are crucial for national development and security.","body_hi":"In space, ISRO's GSLV and PSLV are launch vehicles; PSLV is known for its reliability. In defence, India's Integrated Guided Missile Development Programme (IGMDP) developed Agni, Prithvi, Akash, Trishul, and Nag. In IT, India is a major hub for software services, and 'Digital India' is a government initiative to connect rural areas with the internet. These fields are crucial for national development and security."}}],"questions":[{"q":"Which was India's first satellite launched in 1975?","q_hi":"1975 में प्रक्षेपित भारत का पहला उपग्रह कौन सा था?","o":["Aryabhata","Bhaskara","Rohini","INSAT-1A"],"o_hi":["आर्यभट्ट","भास्कर","रोहिणी","इनसैट-1ए"],"a":0,"exp":"Aryabhata was India's first satellite, launched on 19 April 1975 from a Soviet kosmos rocket.","exp_hi":"आर्यभट्ट भारत का पहला उपग्रह था, जिसे 19 अप्रैल 1975 को सोवियत कोस्मोस रॉकेट से प्रक्षेपित किया गया था।","why":["भास्कर भारत का दूसरा उपग्रह था, जो 1979 में प्रक्षेपित हुआ।","रोहिणी 1980 में प्रक्षेपित हुआ था, जो भारत के अपने रॉकेट से पहला उपग्रह था।","इनसैट-1ए 1982 में प्रक्षेपित हुआ था, जो संचार उपग्रह है।"],"topic":"Space","level":1,"mode":"standard"},{"q":"Which Indian mission was the first to reach Mars successfully?","q_hi":"कौन सा भारतीय मिशन मंगल ग्रह पर सफलतापूर्वक पहुँचने वाला पहला मिशन था?","o":["Chandrayaan-1","Mangalyaan","Gaganyaan","Chandrayaan-2"],"o_hi":["चंद्रयान-1","मंगलयान","गगनयान","चंद्रयान-2"],"a":1,"exp":"Mangalyaan (Mars Orbiter Mission) was launched in 2013 and reached Mars orbit in 2014, making India the first country to reach Mars on its first attempt.","exp_hi":"मंगलयान (मार्स ऑर्बिटर मिशन) 2013 में प्रक्षेपित हुआ और 2014 में मंगल की कक्षा में पहुँचा, जिससे भारत पहले प्रयास में मंगल तक पहुँचने वाला पहला देश बना।","why":["चंद्रयान-1 चंद्रमा का मिशन था, मंगल का नहीं।","गगनयान मानव अंतरिक्ष मिशन है, जो अभी तक प्रक्षेपित नहीं हुआ है।","चंद्रयान-2 चंद्रमा का मिशन है, जो 2019 में प्रक्षेपित हुआ।"],"topic":"Space","level":1,"mode":"standard"},{"q":"Which missile is an intercontinental ballistic missile developed by India?","q_hi":"भारत द्वारा विकसित अंतरमहाद्वीपीय बैलिस्टिक मिसाइल कौन सी है?","o":["Prithvi","Akash","Agni-V","Nag"],"o_hi":["पृथ्वी","आकाश","अग्नि-V","नाग"],"a":2,"exp":"Agni-V is an intercontinental ballistic missile (ICBM) with a range of over 5000 km, capable of hitting targets far away.","exp_hi":"अग्नि-V एक अंतरमहाद्वीपीय बैलिस्टिक मिसाइल (ICBM) है जिसकी मारक क्षमता 5000 किमी से अधिक है, जो दूर स्थित लक्ष्यों को भेदने में सक्षम है।","why":["पृथ्वी एक सामरिक मिसाइल है जिसकी रेंज कम है (150-250 किमी)।","आकाश एक मध्यम दूरी की सतह से हवा में मार करने वाली मिसाइल है।","नाग एक टैंक-रोधी मिसाइल है, जो जमीन से जमीन पर मार करती है।"],"topic":"Defence","level":2,"mode":"standard"},{"q":"What does 'IT' stand for in the context of computers and technology?","q_hi":"कंप्यूटर और प्रौद्योगिकी के संदर्भ में 'आईटी' का पूर्ण रूप क्या है?","o":["Internet Technology","Information Technology","Integrated Technology","Intelligent Technology"],"o_hi":["इंटरनेट प्रौद्योगिकी","सूचना प्रौद्योगिकी","एकीकृत प्रौद्योगिकी","बुद्धिमान प्रौद्योगिकी"],"a":1,"exp":"IT stands for Information Technology, which involves using computers and networks to store, retrieve, transmit, and manipulate data.","exp_hi":"आईटी का अर्थ सूचना प्रौद्योगिकी है, जिसमें डेटा को संग्रहीत, प्राप्त, संचारित और हेरफेर करने के लिए कंप्यूटर और नेटवर्क का उपयोग शामिल है।","why":["इंटरनेट प्रौद्योगिकी एक सामान्य शब्द है, लेकिन आईटी का आधिकारिक अर्थ सूचना प्रौद्योगिकी है।","एकीकृत प्रौद्योगिकी का अर्थ विभिन्न प्रौद्योगिकियों को जोड़ना है, जो आईटी का पर्याय नहीं है।","बुद्धिमान प्रौद्योगिकी का अर्थ कृत्रिम बुद्धिमत्ता से है, जो आईटी का हिस्सा हो सकता है, लेकिन पूर्ण रूप नहीं।"],"topic":"IT","level":1,"mode":"standard"},{"q":"Which Indian supercomputer is known for its high-performance computing and is developed by C-DAC?","q_hi":"सी-डैक द्वारा विकसित भारत का कौन सा सुपरकंप्यूटर उच्च-प्रदर्शन कंप्यूटिंग के लिए जाना जाता है?","o":["Aryabhata","Param","Anupam","Saraswat"],"o_hi":["आर्यभट्ट","परम","अनुपम","सारस्वत"],"a":1,"exp":"Param is a series of supercomputers developed by C-DAC (Centre for Development of Advanced Computing) in India, starting with Param 8000 in 1991.","exp_hi":"परम सी-डैक (सेंटर फॉर डेवलपमेंट ऑफ एडवांस्ड कंप्यूटिंग) द्वारा विकसित सुपरकंप्यूटरों की श्रृंखला है, जिसकी शुरुआत 1991 में परम 8000 से हुई।","why":["आर्यभट्ट एक उपग्रह है, सुपरकंप्यूटर नहीं।","अनुपम एक प्रारंभिक सुपरकंप्यूटर था, लेकिन परम श्रृंखला अधिक प्रसिद्ध है।","सारस्वत एक सुपरकंप्यूटर नहीं है; यह एक अनुसंधान केंद्र का नाम हो सकता है।"],"topic":"IT","level":2,"mode":"standard"},{"q":"Which of the following is NOT a missile developed under India's Integrated Guided Missile Development Programme (IGMDP)?","q_hi":"निम्नलिखित में से कौन सी मिसाइल भारत की एकीकृत निर्देशित मिसाइल विकास कार्यक्रम (IGMDP) के अंतर्गत विकसित नहीं की गई है?","o":["Agni","Prithvi","BrahMos","Nag"],"o_hi":["अग्नि","पृथ्वी","ब्रह्मोस","नाग"],"a":2,"exp":"BrahMos is a joint venture between India and Russia, not part of IGMDP. IGMDP developed Agni, Prithvi, Akash, Trishul, and Nag.","exp_hi":"ब्रह्मोस भारत और रूस की संयुक्त परियोजना है, जो IGMDP का हिस्सा नहीं है। IGMDP ने अग्नि, पृथ्वी, आकाश, त्रिशूल और नाग विकसित कीं।","why":["अग्नि IGMDP के अंतर्गत विकसित की गई थी।","पृथ्वी IGMDP के अंतर्गत विकसित की गई थी।","नाग IGMDP के अंतर्गत विकसित की गई थी।"],"topic":"Defence","level":3,"mode":"standard"}]}]/*__DATA_END__*/);
